from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
CENT = Decimal('0.01')
ZERO = Decimal('0.00')

def _q(value):
    with localcontext() as ctx:
        ctx.prec = 80
        return value.quantize(CENT, rounding=ROUND_HALF_UP)

def _money(value):
    if not isinstance(value, str):
        raise ValueError('money must be a string')
    try:
        parsed = Decimal(value)
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid money value') from None
    if not parsed.is_finite():
        raise ValueError('money must be finite')
    if parsed.as_tuple().exponent < -2:
        raise ValueError('money must have at most 2 decimal places')
    return _q(parsed)

def _validated(lines):
    if not isinstance(lines, (list, tuple)):
        raise ValueError('lines must be a list')
    out = []
    for entry in lines:
        if not isinstance(entry, dict):
            raise ValueError('line must be a dict')
        if 'name' not in entry or 'kind' not in entry or 'budget' not in entry or 'actual' not in entry:
            raise ValueError('line missing keys')
        name = entry['name']
        kind = entry['kind']
        if not isinstance(name, str):
            raise ValueError('name must be a string')
        if kind not in ('revenue', 'cost'):
            raise ValueError('invalid kind')
        out.append((name, kind, _money(entry['budget']), _money(entry['actual'])))
    return out

def _info(kind, budget, actual):
    variance = _q(actual - budget)
    if kind == 'revenue':
        favourable = variance > Decimal('0')
    else:
        favourable = variance < Decimal('0')
    if variance == Decimal('0'):
        status = 'on_budget'
    elif favourable:
        status = 'favourable'
    else:
        status = 'unfavourable'
    return variance, favourable, status

def variance_report(lines):
    result = []
    for name, kind, budget, actual in _validated(lines):
        variance, favourable, status = _info(kind, budget, actual)
        if budget == Decimal('0'):
            percent = None
        else:
            with localcontext() as ctx:
                ctx.prec = 80
                percent = (variance / budget * Decimal('100')).quantize(CENT, rounding=ROUND_HALF_UP)
        result.append({'name': name, 'kind': kind, 'budget': budget, 'actual': actual, 'variance': variance, 'variance_percent': percent, 'favourable': favourable, 'status': status})
    return result

def variance_summary(lines):
    total_budget_revenue = ZERO
    total_actual_revenue = ZERO
    total_budget_cost = ZERO
    total_actual_cost = ZERO
    favourable_count = 0
    unfavourable_count = 0
    on_budget_count = 0
    for name, kind, budget, actual in _validated(lines):
        variance, favourable, status = _info(kind, budget, actual)
        if kind == 'revenue':
            total_budget_revenue = _q(total_budget_revenue + budget)
            total_actual_revenue = _q(total_actual_revenue + actual)
        else:
            total_budget_cost = _q(total_budget_cost + budget)
            total_actual_cost = _q(total_actual_cost + actual)
        if status == 'favourable':
            favourable_count += 1
        elif status == 'on_budget':
            on_budget_count += 1
        else:
            unfavourable_count += 1
    net_budget = _q(total_budget_revenue - total_budget_cost)
    net_actual = _q(total_actual_revenue - total_actual_cost)
    net_variance = _q(net_actual - net_budget)
    return {'total_budget_revenue': _q(total_budget_revenue), 'total_actual_revenue': _q(total_actual_revenue), 'total_budget_cost': _q(total_budget_cost), 'total_actual_cost': _q(total_actual_cost), 'net_budget': net_budget, 'net_actual': net_actual, 'net_variance': net_variance, 'favourable_count': favourable_count, 'unfavourable_count': unfavourable_count, 'on_budget_count': on_budget_count}

