from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
CENT = Decimal('0.01')
ZERO = Decimal('0.00')

def _q(value):
    with localcontext() as ctx:
        ctx.prec = 80
        return value.quantize(CENT, rounding=ROUND_HALF_UP)

def _money(value):
    if not isinstance(value, str):
        raise ValueError('money must be a string')
    try:
        parsed = Decimal(value)
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid money value') from None
    if not parsed.is_finite():
        raise ValueError('money must be finite')
    if parsed.as_tuple().exponent < -2:
        raise ValueError('money must have at most 2 decimal places')
    return _q(parsed)

def _parse_factor(value):
    if not isinstance(value, str):
        raise ValueError('factor must be a string')
    try:
        parsed = Decimal(value)
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid factor') from None
    if not parsed.is_finite():
        raise ValueError('factor must be finite')
    if parsed < Decimal('1') or parsed > Decimal('3'):
        raise ValueError('factor out of range')
    return parsed

def declining_schedule(cost, salvage, life_years, factor='2'):
    cost_dec = _money(cost)
    salvage_dec = _money(salvage)
    if isinstance(life_years, bool) or not isinstance(life_years, int):
        raise ValueError('life_years must be an int')
    if life_years < 1 or life_years > 50:
        raise ValueError('life_years out of range')
    factor_dec = _parse_factor(factor)
    if salvage_dec < Decimal('0') or not cost_dec > salvage_dec:
        raise ValueError('cost must be greater than salvage')
    rows = []
    accumulated = ZERO
    opening = cost_dec
    for year in range(1, life_years + 1):
        if year == life_years:
            amount = _q(opening - salvage_dec)
        else:
            remaining_years = life_years - year + 1
            with localcontext() as ctx:
                ctx.prec = 80
                declining = opening * (factor_dec / Decimal(life_years))
                straight = (opening - salvage_dec) / Decimal(remaining_years)
                raw = declining if declining >= straight else straight
                amount = raw.quantize(CENT, rounding=ROUND_HALF_UP)
            cap = _q(opening - salvage_dec)
            if amount > cap:
                amount = cap
        accumulated = _q(accumulated + amount)
        book_value = _q(cost_dec - accumulated)
        rows.append({'year': year, 'amount': _q(amount), 'accumulated': accumulated, 'book_value': book_value})
        opening = book_value
    return rows

