from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
CENT = Decimal('0.01')
ZERO = Decimal('0.00')

def _q(value):
    with localcontext() as ctx:
        ctx.prec = 80
        return value.quantize(CENT, rounding=ROUND_HALF_UP)

def _money(value):
    if not isinstance(value, str):
        raise ValueError('money must be a string')
    try:
        parsed = Decimal(value)
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid money value') from None
    if not parsed.is_finite():
        raise ValueError('money must be finite')
    if parsed.as_tuple().exponent < -2:
        raise ValueError('money must have at most 2 decimal places')
    return _q(parsed)

def _check_int(value, low, high, label):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(label)
    if value < low or value > high:
        raise ValueError(label)
    return value

def straight_line_schedule(cost, salvage, life_years, placed_year, placed_month):
    cost_dec = _money(cost)
    salvage_dec = _money(salvage)
    if cost_dec <= Decimal('0') or salvage_dec < Decimal('0') or not salvage_dec < cost_dec:
        raise ValueError('invalid cost or salvage')
    life_years = _check_int(life_years, 1, 50, 'life_years out of range')
    placed_year = _check_int(placed_year, 1900, 2200, 'placed_year out of range')
    placed_month = _check_int(placed_month, 1, 12, 'placed_month out of range')
    base = _q(cost_dec - salvage_dec)
    rows = []
    accumulated = ZERO
    remaining = base
    year = placed_year
    is_first = True
    while remaining > Decimal('0'):
        with localcontext() as ctx:
            ctx.prec = 80
            full = base / Decimal(life_years)
            if is_first:
                fraction = (Decimal(12 - placed_month) + Decimal('0.5')) / Decimal(12)
                raw = full * fraction
            else:
                raw = full
            quantized = raw.quantize(CENT, rounding=ROUND_HALF_UP)
        if quantized >= remaining or quantized <= Decimal('0'):
            amount = remaining
        else:
            amount = quantized
        accumulated = _q(accumulated + amount)
        book_value = _q(cost_dec - accumulated)
        rows.append({'year': year, 'amount': _q(amount), 'accumulated': accumulated, 'book_value': book_value})
        remaining = _q(remaining - amount)
        year += 1
        is_first = False
    return rows
